/** Các hàm tiện ích xử lý Date an toàn cho backend. */

/**
 * Chuyển đổi một giá trị Date (hoặc string từ DB driver) sang ISO string an toàn.
 * Giúp tránh lỗi .toISOString() is not a function nếu driver trả về string thay vì Date object.
 */
export function safeIsoString(d: unknown): string | null {
  if (d == null) return null;
  if (d instanceof Date) {
    try {
      return d.toISOString();
    } catch {
      return null;
    }
  }
  if (typeof d === 'string') {
    // Nếu là string đã có định dạng ISO hoặc gần giống, trả về luôn
    // Có thể thêm regex check nếu cần khắt khe hơn
    return d;
  }
  return null;
}

/**
 * Trả về ISO string hiện tại (now) nếu giá trị input null/không hợp lệ.
 */
export function safeIsoStringNow(d: unknown): string {
  return safeIsoString(d) || new Date().toISOString();
}

src/common/dev-login-options.ts.content:
import type { Role } from '../entities/role.entity';
import type { User } from '../entities/user.entity';
import type { UserRole } from '../entities/user-role.entity';

export type DevLoginRoleDto = {
  id: number;
  name: string;
  displayName: string;
};

export type DevLoginOptionDto = {
  id: number;
  email: string;
  name: string | null;
  isActive: boolean;
  roleNames: string[];
  roleLabels: string[];
  roles: DevLoginRoleDto[];
  description: string;
};

export type DevLoginOptionsQuery = {
  /** Lọc user có role này (vd. student). */
  role?: string;
  /** Lọc user có ít nhất một role (vd. parent,user). */
  roles?: string;
  /** Loại user có bất kỳ role nào trong danh sách. */
  excludeRoles?: string;
  /** Lọc email kết thúc bằng hậu tố (vd. @st.buh.edu.vn). */
  emailSuffix?: string;
  /** Mặc định true — chỉ user đang hoạt động. */
  activeOnly?: boolean;
};

function parseCsv(value: string | undefined): string[] {
  if (!value?.trim()) return [];
  return [
    ...new Set(
      value
        .split(',')
        .map((part) => part.trim().toLowerCase())
        .filter(Boolean),
    ),
  ];
}

function listUserRoles(userRoles: UserRole[] | undefined): DevLoginRoleDto[] {
  const roles = (userRoles ?? [])
    .map((userRole) => userRole.role)
    .filter((role): role is Role => Boolean(role && role.deletedAt == null));

  const seen = new Set<number>();
  return roles
    .map((role) => ({
      id: role.id,
      name: role.name.trim(),
      displayName: (role.displayName?.trim() || role.name).trim(),
    }))
    .filter((role) => {
      if (!role.name || seen.has(role.id)) return false;
      seen.add(role.id);
      return true;
    });
}

export function mapUserToDevLoginOption(user: User): DevLoginOptionDto | null {
  const email = user.email?.trim() ?? '';
  if (!email) return null;

  const roles = listUserRoles(user.userRoles);
  const roleNames = roles.map((role) => role.name);
  const roleLabels = roles.map((role) => role.displayName);
  const statusLabel = user.isActive ? 'Đang hoạt động' : 'Ngừng hoạt động';
  const roleDescription =
    roleLabels.length > 0 ? roleLabels.join(', ') : 'Chưa gán vai trò';

  return {
    id: user.id,
    email,
    name: user.name ?? null,
    isActive: user.isActive,
    roleNames,
    roleLabels,
    roles,
    description: `${statusLabel} | ${roleDescription}`,
  };
}

export function filterDevLoginOptions(
  options: DevLoginOptionDto[],
  query: DevLoginOptionsQuery = {},
): DevLoginOptionDto[] {
  const role = query.role?.trim().toLowerCase();
  const roles = parseCsv(query.roles);
  const excludeRoles = parseCsv(query.excludeRoles);
  const emailSuffix = query.emailSuffix?.trim().toLowerCase();
  const activeOnly = query.activeOnly !== false;

  return options.filter((option) => {
    const names = option.roleNames.map((name) => name.toLowerCase());

    if (activeOnly && !option.isActive) return false;
    if (role && !names.includes(role)) return false;
    if (roles.length > 0 && !roles.some((name) => names.includes(name))) {
      return false;
    }
    if (
      excludeRoles.length > 0 &&
      excludeRoles.some((name) => names.includes(name))
    ) {
      return false;
    }
    if (
      emailSuffix &&
      !option.email.trim().toLowerCase().endsWith(emailSuffix)
    ) {
      return false;
    }
    return true;
  });
}

src/common/entity-id.ts.content:
import { BadRequestException } from '@nestjs/common';

export type EntityId = number;

/** Parse id từ route param / query (luôn là chuỗi trên HTTP). */
export function parseEntityId(
  value: string | number | null | undefined,
): number {
  if (value == null || value === '') {
    throw new BadRequestException('Thiếu id.');
  }
  const n =
    typeof value === 'number'
      ? value
      : Number.parseInt(String(value).trim(), 10);
  if (!Number.isFinite(n) || n <= 0) {
    throw new BadRequestException('Id không hợp lệ.');
  }
  return n;
}

export function isEntityId(value: string): boolean {
  const n = Number.parseInt(value.trim(), 10);
  return Number.isFinite(n) && n > 0 && String(n) === value.trim();
}

/** Route param / body — chấp nhận string hoặc number. */
export function toEntityId(value: string | number): number {
  return typeof value === 'number' ? value : parseEntityId(value);
}

export function toEntityIdList(values: Array<string | number>): number[] {
  return values.map((v) => toEntityId(v));
}

/** Chỉ giữ id hợp lệ — bỏ UUID/CUID legacy khi lọc FK import. */
export function toEntityIdListSafe(values: Array<string | number>): number[] {
  const out: number[] = [];
  for (const v of values) {
    const id = relationEntityId(v);
    if (id != null) out.push(id);
  }
  return out;
}

/** Lấy id số từ relation đã populate hoặc scalar (DTO / mapRow). */
export function relationEntityId(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value) && value > 0) {
    return value;
  }
  if (typeof value === 'string' && value.trim()) {
    const trimmed = value.trim();
    if (isEntityId(trimmed)) return parseEntityId(trimmed);
  }
  if (value && typeof value === 'object' && 'id' in value) {
    return relationEntityId((value as { id?: unknown }).id);
  }
  return null;
}

/**
 * PK import: chỉ giữ id số nguyên dương hợp lệ (không nhận UUID/CUID legacy).
 * Trả về undefined để caller bỏ qua field → DB autoincrement.
 */
export function coerceImportPrimaryKey(value: unknown): number | undefined {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return value;
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (isEntityId(trimmed)) return parseEntityId(trimmed);
  }
  return undefined;
}

src/common/event-time-status.ts.content:
export type EventTimeStatus = 'upcoming' | 'ongoing' | 'past';

function toValidDate(value: Date | string | null | undefined): Date | null {
  if (value == null) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Trạng thái thời gian sự kiện — khớp bộ lọc public list:
 * - upcoming: startDate > now
 * - ongoing: startDate <= now && endDate >= now
 * - past: endDate < now, hoặc đã bắt đầu nhưng không có endDate
 */
export function resolveEventTimeStatus(
  startDate: Date | string | null | undefined,
  endDate: Date | string | null | undefined,
  now: Date = new Date(),
): EventTimeStatus {
  const start = toValidDate(startDate);
  const end = toValidDate(endDate);
  const nowMs = now.getTime();

  if (start && start.getTime() > nowMs) {
    return 'upcoming';
  }

  if (end && end.getTime() < nowMs) {
    return 'past';
  }

  if (start && end && start.getTime() <= nowMs && end.getTime() >= nowMs) {
    return 'ongoing';
  }

  if (start && start.getTime() <= nowMs) {
    return 'past';
  }

  return 'upcoming';
}

src/common/fs-unlink-retry.ts.content:
import { unlink } from 'fs/promises';

const RETRYABLE_CODES = new Set(['EBUSY', 'EPERM', 'EACCES']);

export type UnlinkWithRetryOptions = {
  maxAttempts?: number;
  baseDelayMs?: number;
  /** Không ném lỗi khi file đã không tồn tại. */
  ignoreMissing?: boolean;
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Xóa file trên disk — retry khi Windows/antivirus/Sharp giữ handle (EBUSY).
 */
export async function unlinkWithRetry(
  filePath: string,
  options: UnlinkWithRetryOptions = {},
): Promise<void> {
  const isWin = process.platform === 'win32';
  const maxAttempts = options.maxAttempts ?? (isWin ? 10 : 4);
  const baseDelayMs = options.baseDelayMs ?? (isWin ? 150 : 50);
  const ignoreMissing = options.ignoreMissing ?? false;

  let lastError: unknown;
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      await unlink(filePath);
      return;
    } catch (err) {
      lastError = err;
      const errno = err as NodeJS.ErrnoException;
      if (errno.code === 'ENOENT' && ignoreMissing) return;
      if (
        attempt < maxAttempts - 1 &&
        errno.code &&
        RETRYABLE_CODES.has(errno.code)
      ) {
        await sleep(baseDelayMs * (attempt + 1));
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

src/common/get-options.ts.content:
import { EntityRepository, type FilterQuery } from '@mikro-orm/core';

export interface GetOptionsColumnConfig {
  valueField: string;
  labelField?: string;
  searchField?: string;
}

export type GetOptionsConfig = Record<string, GetOptionsColumnConfig>;

function getColumnConfig(
  column: string,
  config: GetOptionsConfig,
): GetOptionsColumnConfig {
  const candidate = config[column] ?? config['*'];
  if (candidate) return candidate;

  return {
    valueField: column,
    labelField: column,
    searchField: column,
  };
}

export async function getOptionsFromModel<T extends object>(
  delegate: EntityRepository<T>,
  baseWhere: Record<string, unknown>,
  column: string,
  config: GetOptionsConfig,
  search?: string,
  limit = 50,
): Promise<Array<{ label: string; value: string }>> {
  const col = getColumnConfig(column, config);
  const valueField = col.valueField;
  const labelField = col.labelField ?? valueField;
  const searchField = col.searchField ?? labelField;

  const where = { ...(baseWhere as FilterQuery<T>) } as FilterQuery<T>;
  if (search?.trim()) {
    (where as Record<string, unknown>)[searchField] = {
      $like: `%${search.trim()}%`,
    };
  }

  const fields =
    valueField === labelField ? [valueField] : [valueField, labelField];

  const rows = await delegate.find(where, {
    fields: fields as any,
    orderBy: { [labelField]: 'ASC' } as any,
    limit,
  });

  if (valueField !== labelField) {
    const seen = new Set<string>();
    return rows
      .map((row: any) => {
        const value = row[valueField];
        const label = row[labelField];
        const normalizedValue = typeof value === 'string' ? value.trim() : '';
        const normalizedLabel =
          typeof label === 'string' ? label.trim() : normalizedValue;
        return normalizedValue
          ? {
              value: normalizedValue,
              label: normalizedLabel || normalizedValue,
            }
          : null;
      })
      .filter((item): item is { value: string; label: string } => item != null)
      .filter((item) => {
        if (seen.has(item.value)) return false;
        seen.add(item.value);
        return true;
      });
  }

  const seen = new Set<string>();
  return rows
    .map((row: any) => row[valueField] as string)
    .filter(
      (value): value is string =>
        typeof value === 'string' && value.trim() !== '',
    )
    .filter((value) => {
      if (seen.has(value)) return false;
      seen.add(value);
      return true;
    })
    .map((value) => ({ label: value, value }));
}

src/common/image-processor.ts.content:
import sharp from 'sharp';

export interface ImageProcessOptions {
  maxWidth?: number;
  quality?: number;
}

const DEFAULT_MAX_WIDTH = 1920;
const DEFAULT_QUALITY = 80;

export function isImageMime(mime: string): boolean {
  return mime.startsWith('image/') && !mime.includes('svg');
}

export function isImageExt(ext: string): boolean {
  return [
    '.jpg',
    '.jpeg',
    '.png',
    '.gif',
    '.webp',
    '.bmp',
    '.tif',
    '.tiff',
    '.heic',
    '.heif',
  ].includes(ext.toLowerCase());
}

export async function processImageBuffer(
  buffer: Buffer,
  options?: ImageProcessOptions,
): Promise<{
  webpBuffer: Buffer;
  originalFormat: string;
  width: number;
  height: number;
}> {
  const maxWidth = options?.maxWidth ?? DEFAULT_MAX_WIDTH;
  const quality = options?.quality ?? DEFAULT_QUALITY;

  let image = sharp(buffer);
  const metadata = await image.metadata();
  const originalFormat = metadata.format ?? 'jpeg';
  let width = metadata.width ?? 0;
  let height = metadata.height ?? 0;

  if (width > maxWidth) {
    const ratio = maxWidth / width;
    width = maxWidth;
    height = Math.round(height * ratio);
    image = image.resize(maxWidth, undefined, {
      fit: 'inside',
      withoutEnlargement: true,
    });
  }

  const webpBuffer = await image.webp({ quality }).toBuffer();
  return { webpBuffer, originalFormat, width, height };
}

src/common/legacy-audit-timestamps.ts.content:
/** Bản ghi legacy có created_at / updated_at nullable. */
export type LegacyAuditEntity = {
  createdAt?: Date | null;
  updatedAt?: Date | null;
};

export function touchLegacyAuditTimestamps(
  entity: LegacyAuditEntity,
  isCreate = false,
): void {
  const now = new Date();
  if (isCreate || !entity.createdAt) {
    entity.createdAt = entity.createdAt ?? now;
  }
  entity.updatedAt = now;
}

export function backfillLegacyAuditTimestampsIfMissing(
  entity: LegacyAuditEntity,
): boolean {
  const now = new Date();
  let changed = false;
  if (!entity.createdAt) {
    entity.createdAt = now;
    changed = true;
  }
  if (!entity.updatedAt) {
    entity.updatedAt = entity.createdAt ?? now;
    changed = true;
  }
  return changed;
}

src/common/logging.interceptor.ts.content:
import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import type { Request, Response } from 'express';
import { appConfig } from '../config/app.config';
import { APP_HEADERS } from '../config/constants';
import { REQUEST_ID_HEADER } from './request-id.middleware';

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger('HTTP');

  private readonly bodyMaxLen = appConfig.logging.httpLogBodyMaxLen;
  private readonly errorMaxLen = appConfig.logging.httpLogErrorMaxLen;
  private readonly responseMaxLen = appConfig.logging.httpLogResponseMaxLen;
  private readonly logSuccessBody = appConfig.logging.httpLogSuccessBody;

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const http = context.switchToHttp();
    const req = http.getRequest<Request>();
    const res = http.getResponse<Response>();
    const method = req.method;
    const url = req.url ?? req.originalUrl ?? '';
    const ip = req.ip ?? req.socket?.remoteAddress ?? '';
    const query = req.query as Record<string, unknown>;
    const body: unknown = req.body;
    const start = Date.now();
    const ts = new Date().toISOString();
    const userId =
      (req.headers[APP_HEADERS.USER_ID.toLowerCase()] as string)?.trim() || '-';
    const contentType = (req.headers['content-type'] as string) || '-';
    const requestId = (req.headers[REQUEST_ID_HEADER] as string) || '-';
    const controllerName = context.getClass().name || '-';
    const handlerName = context.getHandler().name || '-';
    const endpoint = `${controllerName}.${handlerName}`;
    const queryStr = Object.keys(query).length ? JSON.stringify(query) : '-';
    const bodyStr =
      this.bodyMaxLen === 0
        ? this.safeStringify(
            this.sanitizePayload(body),
            Number.MAX_SAFE_INTEGER,
          )
        : this.safeStringify(this.sanitizePayload(body), this.bodyMaxLen);
    const apiTag = this.buildApiTag(url);
    this.logger.log(
      `\n┌── REQUEST ${apiTag} ── ${ts} ── req:${requestId}\n` +
        `│  ${method} ${url}\n` +
        `│  endpoint     ${endpoint}\n` +
        `│  ip           ${ip}\n` +
        `│  ${APP_HEADERS.USER_ID}    ${userId}\n` +
        `│  req-id       ${requestId}\n` +
        `│  content-type ${contentType}\n` +
        `│  query        ${queryStr}\n` +
        `│  body         ${bodyStr}\n` +
        `└─────────────`,
    );

    const originalJson = res.json.bind(res) as (body: unknown) => Response;
    res.json = (responseBody: unknown) => {
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      const duration = Date.now() - start;
      const summary = this.summaryBody(responseBody);
      const status = res.statusCode;
      const statusIcon = status >= 500 ? '✗' : status >= 400 ? '⚠' : '✓';
      const sanitizedResponse = this.sanitizePayload(responseBody);
      const responseSize = this.getResponseSize(sanitizedResponse);
      const payloadPreview = this.safeStringify(
        sanitizedResponse,
        this.responseMaxLen,
      );
      const bodyLines =
        this.logSuccessBody &&
        sanitizedResponse !== undefined &&
        sanitizedResponse !== null
          ? [
              '│  response:',
              ...this.formatBodyLines(sanitizedResponse, this.responseMaxLen),
            ]
          : [];
      this.logger.log(
        `\n┌── RESPONSE ${statusIcon} ${status} ${apiTag} ── ${duration}ms ── size:${responseSize} ── req:${requestId}\n` +
          `│  ${method} ${url}\n` +
          `│  endpoint   ${endpoint}\n` +
          `│  ${APP_HEADERS.USER_ID}   ${userId}\n` +
          `│  req-id     ${requestId}\n` +
          `│  summary    ${summary}\n` +
          `│  preview    ${payloadPreview}\n` +
          (!this.logSuccessBody
            ? `│  response   [hidden for success logs, set HTTP_LOG_SUCCESS_BODY=true to show]\n`
            : '') +
          (bodyLines.length > 0 ? bodyLines.join('\n') + '\n' : '') +
          `└─────────────`,
      );
      (res as unknown as { _jsonLogged?: boolean })._jsonLogged = true;
      return originalJson(responseBody);
    };

    return next.handle().pipe(
      tap({
        next: () => {
          const resAny = res as unknown as { _jsonLogged?: boolean };
          if (!resAny._jsonLogged) {
            const duration = Date.now() - start;
            this.logger.log(
              `\n┌── RESPONSE ✓ ${res.statusCode} ${apiTag} ── ${duration}ms ── req:${requestId}\n` +
                `│  ${method} ${url}\n` +
                `│  endpoint  ${endpoint}\n` +
                `│  ${APP_HEADERS.USER_ID}  ${userId}\n` +
                `│  req-id    ${requestId}\n` +
                `└─────────────`,
            );
          }
        },
        error: (err: unknown) => {
          const duration = Date.now() - start;
          const errorDetail = this.buildErrorDetail(err);
          const queryDebug =
            this.bodyMaxLen === 0
              ? this.safeStringify(
                  this.sanitizePayload(query),
                  Number.MAX_SAFE_INTEGER,
                )
              : this.safeStringify(
                  this.sanitizePayload(query),
                  this.bodyMaxLen,
                );
          const bodyDebug =
            this.bodyMaxLen === 0
              ? this.safeStringify(
                  this.sanitizePayload(body),
                  Number.MAX_SAFE_INTEGER,
                )
              : this.safeStringify(this.sanitizePayload(body), this.bodyMaxLen);
          this.logger.error(
            `\n┌── RESPONSE ✗ ERROR ${apiTag} ── ${duration}ms ── req:${requestId}\n` +
              `│  ${method} ${url}\n` +
              `│  endpoint  ${endpoint}\n` +
              `│  ${APP_HEADERS.USER_ID}  ${userId}\n` +
              `│  req-id    ${requestId}\n` +
              `│  query     ${queryDebug}\n` +
              `│  body      ${bodyDebug}\n` +
              `│  error     ${errorDetail.summary}\n` +
              `│  details:\n` +
              this.formatBodyLines(this.sanitizePayload(errorDetail.details))
                .map((line) => `${line}\n`)
                .join('') +
              `└─────────────`,
          );
        },
      }),
    );
  }

  private buildErrorDetail(err: unknown): {
    summary: string;
    details: Record<string, unknown>;
  } {
    if (!(err instanceof Error)) {
      return {
        summary: this.safeStringify(err, 200),
        details: { raw: this.safeStringify(err, this.errorMaxLen) },
      };
    }

    const asAny = err as any;
    const stack =
      typeof err.stack === 'string'
        ? err.stack.split('\n').slice(0, 20).join('\n')
        : undefined;
    const details: Record<string, unknown> = {
      name: err.name,
      message: err.message,
      code: asAny.code,
      status: asAny.status ?? asAny.statusCode,
      sqlState: asAny.sqlState,
      sqlMessage: asAny.sqlMessage,
      sql: asAny.sql,
      response: asAny.response,
      cause: asAny.cause,
      stack,
    };

    return {
      summary: `${err.name}: ${err.message}`,
      details,
    };
  }

  private buildApiTag(url: string): string {
    const clean = (url || '').split('?')[0];
    const segments = clean.split('/').filter(Boolean);
    const apiIdx = segments.indexOf('api');
    if (apiIdx === -1) return '[UNKNOWN]';
    const scope = (segments[apiIdx + 1] || 'unknown').toUpperCase();
    const resource = (segments[apiIdx + 2] || 'root').toUpperCase();
    return `[${scope}/${resource}]`;
  }

  private sanitizePayload(value: unknown): unknown {
    const sensitiveKeys = new Set([
      'password',
      'accessToken',
      'refreshToken',
      'token',
      'authorization',
      'cookie',
    ]);
    const visited = new WeakSet<object>();

    const walk = (input: unknown): unknown => {
      if (input === null || input === undefined) return input;
      if (typeof input !== 'object') return input;
      if (visited.has(input)) return '[circular]';
      visited.add(input);

      if (Array.isArray(input)) return input.map(walk);

      const out: Record<string, unknown> = {};
      for (const [key, val] of Object.entries(
        input as Record<string, unknown>,
      )) {
        if (sensitiveKeys.has(key) || sensitiveKeys.has(key.toLowerCase())) {
          out[key] = '[REDACTED]';
          continue;
        }
        out[key] = walk(val);
      }
      return out;
    };

    return walk(value);
  }

  private summaryBody(value: unknown): string {
    if (value === undefined || value === null) return '-';
    if (
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean'
    )
      return String(value);
    if (typeof value === 'object') {
      const o = value as Record<string, unknown>;
      const success = o.success;
      const data = o.data;
      const msg = o.message;
      const errVal = o.error;
      const parts: string[] = [];
      if (typeof success === 'boolean') parts.push(`success: ${success}`);
      if (msg != null)
        parts.push(
          `message: "${this.safeStringify(msg, 50).replace(/"/g, '')}"`,
        );
      if (errVal != null && o.success === false)
        parts.push(`error: ${this.safeStringify(errVal, 80)}`);
      if (data != null) {
        if (Array.isArray(data)) {
          parts.push(`data: ${data.length} item(s)`);
        } else if (
          typeof data === 'object' &&
          data !== null &&
          'data' in data
        ) {
          const inner = (data as { data?: unknown }).data;
          if (Array.isArray(inner)) {
            parts.push(`data.data: ${inner.length} item(s)`);
          } else {
            parts.push(`data: ${Object.keys(data as object).join(', ')}`);
          }
        } else {
          parts.push(`data: ${Object.keys(data as object).join(', ')}`);
        }
      }
      return parts.length ? parts.join(' | ') : this.safeStringify(value, 100);
    }
    return this.safeStringify(value, 100);
  }

  private safeStringify(value: unknown, maxLen = 200): string {
    if (value === undefined || value === null) return '-';
    if (typeof value === 'object') {
      try {
        const str = JSON.stringify(value);
        return str.length > maxLen ? str.slice(0, maxLen) + '...' : str;
      } catch {
        return '[object]';
      }
    }
    // Primitive only at this point (object handled above)
    return typeof value === 'symbol' ? value.toString() : String(value);
  }

  private getResponseSize(value: unknown): number {
    if (value === undefined || value === null) return 0;
    try {
      return Buffer.byteLength(JSON.stringify(value), 'utf8');
    } catch {
      return 0;
    }
  }

  private formatBodyLines(value: unknown, maxLen = this.errorMaxLen): string[] {
    if (value === undefined || value === null) return [];
    try {
      const raw =
        typeof value === 'object' && value !== null
          ? JSON.stringify(value, null, 2)
          : typeof value === 'symbol'
            ? value.toString()
            : String(value);
      const str =
        maxLen > 0 && raw.length > maxLen ? `${raw.slice(0, maxLen)}...` : raw;
      const lines = str.split('\n');
      return lines.map((line) => `│  ${line}`);
    } catch {
      return [`│  ${this.safeStringify(value, this.errorMaxLen)}`];
    }
  }
}

