type LexicalTextNode = {
  detail: number;
  format: number;
  mode: string;
  style: string;
  text: string;
  type: 'text';
  version: number;
};

type LexicalParagraphNode = {
  children: LexicalTextNode[];
  direction: null;
  format: string;
  indent: number;
  textFormat: number;
  textStyle: string;
  type: 'paragraph';
  version: number;
};

export type LexicalEditorState = {
  root: {
    children: LexicalParagraphNode[];
    direction: null;
    format: string;
    indent: number;
    type: 'root';
    version: number;
  };
};

function paragraph(text: string): LexicalParagraphNode {
  return {
    children: text
      ? [
          {
            detail: 0,
            format: 0,
            mode: 'normal',
            style: '',
            text,
            type: 'text',
            version: 1,
          },
        ]
      : [],
    direction: null,
    format: '',
    indent: 0,
    textFormat: 0,
    textStyle: '',
    type: 'paragraph',
    version: 1,
  };
}

export function lexicalFromPlainText(raw: string): LexicalEditorState {
  const lines = raw
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);

  return {
    root: {
      children:
        lines.length > 0
          ? lines.map((line) => paragraph(line))
          : [paragraph('')],
      direction: null,
      format: '',
      indent: 0,
      type: 'root',
      version: 1,
    },
  };
}

export function isLexicalContentEmpty(value: unknown): boolean {
  if (value == null) return true;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return true;
    try {
      return isLexicalContentEmpty(JSON.parse(trimmed));
    } catch {
      return false;
    }
  }
  if (typeof value !== 'object') return true;

  const root = (value as LexicalEditorState).root;
  if (!root?.children?.length) return true;

  return root.children.every((node) => {
    if (node?.type !== 'paragraph') return false;
    return !node.children?.length;
  });
}

export function isLexicalEditorState(
  value: unknown,
): value is LexicalEditorState {
  if (!value || typeof value !== 'object') return false;
  const root = (value as LexicalEditorState).root;
  return Boolean(root && root.type === 'root' && Array.isArray(root.children));
}

src/seeds/load-export-posts.ts.content:
import * as fs from 'fs';
import * as path from 'path';

export type ExportPostSeedSource = {
  title: string;
  slug: string;
  excerpt: string | null;
  image: string | null;
  published: boolean;
  content: unknown;
};

type ExportBundle = Record<string, unknown>;

function normalizePostRows(bundle: ExportBundle): unknown[] {
  const raw = bundle.post ?? bundle.posts;
  if (Array.isArray(raw)) return raw;
  if (raw && typeof raw === 'object') return Object.values(raw);
  return [];
}

function asString(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed || null;
}

function asBool(value: unknown, fallback = false): boolean {
  if (typeof value === 'boolean') return value;
  if (value === 1 || value === '1' || value === 'true') return true;
  if (value === 0 || value === '0' || value === 'false') return false;
  return fallback;
}

/** Đọc bài viết từ file export JSON (full-export). */
export function loadExportPosts(filePath: string): ExportPostSeedSource[] {
  const resolved = path.resolve(filePath);
  if (!fs.existsSync(resolved)) {
    throw new Error(`Không tìm thấy file export bài viết: ${resolved}`);
  }

  const bundle = JSON.parse(fs.readFileSync(resolved, 'utf8')) as ExportBundle;
  const rows = normalizePostRows(bundle);

  const posts: ExportPostSeedSource[] = [];
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue;
    const record = row as Record<string, unknown>;
    const title = asString(record.title);
    if (!title) continue;

    const slug =
      asString(record.slug) ??
      title
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .slice(0, 80);

    posts.push({
      title,
      slug: slug || `post-${posts.length + 1}`,
      excerpt: asString(record.excerpt),
      image: asString(record.image),
      published: asBool(record.published, true),
      content: record.content ?? null,
    });
  }

  return posts.filter((p) => p.published);
}

src/seeds/superadmin-bootstrap.runner.ts.content:
import * as fs from 'fs';
import * as path from 'path';
import type { EntityManager } from '@mikro-orm/core';
import { User } from '../entities/user.entity';
import { Role } from '../entities/role.entity';
import { UserRole } from '../entities/user-role.entity';
import { PageContent } from '../entities/page-content.entity';
import {
  SUPERADMIN_ROLES_DATA,
  SUPERADMIN_USERS_DATA,
  SUPERADMIN_USER_ROLES_DATA,
} from './superadmin-bootstrap.data';

async function resolveUserRoleLink(
  em: EntityManager,
  link: { userEmail: string; roleName: string },
): Promise<UserRole | null> {
  const user = await em.findOne(User, {
    email: link.userEmail.trim().toLowerCase(),
  });
  const role = await em.findOne(Role, { name: link.roleName.trim() });
  if (!user || !role) return null;

  const existing = await em.findOne(UserRole, { user: user.id, role: role.id });
  if (existing) return existing;

  const ur = new UserRole();
  ur.user = user;
  ur.role = role;
  em.persist(ur);
  return ur;
}

/**
 * Đảm bảo các cặp (user, role) trong seed tồn tại trong user_roles nếu user + role đã có.
 */
export async function ensureSeedUserRoleLinks(
  em: EntityManager,
): Promise<void> {
  for (const link of SUPERADMIN_USER_ROLES_DATA) {
    await resolveUserRoleLink(em, link);
  }

  const conn = em.getConnection();
  const driverName = em.getDriver().constructor.name;
  const isMysql = /mysql|mariadb/i.test(driverName);
  if (isMysql) await conn.execute('SET FOREIGN_KEY_CHECKS = 0');
  await em.flush();
  if (isMysql) await conn.execute('SET FOREIGN_KEY_CHECKS = 1');
}

/** Sau import role (TRUNCATE user_roles), gán lại role cho admin đang thao tác import. */
export async function ensureActingUserRoleAfterImport(
  em: EntityManager,
  actingUserId?: number,
): Promise<void> {
  if (actingUserId == null) return;
  const existing = await em.count(UserRole, { user: actingUserId });
  if (existing > 0) return;

  const user = await em.findOne(User, { id: actingUserId });
  if (!user) return;

  const role =
    (await em.findOne(Role, { name: 'super_admin' })) ??
    (await em.findOne(Role, { isActive: true }, { orderBy: { id: 'ASC' } }));
  if (!role) return;

  const ur = new UserRole();
  ur.user = user;
  ur.role = role;
  em.persist(ur);
  await em.flush();
}

export type SuperadminBootstrapResult = {
  rolesInserted: number;
  rolesUpdated: number;
  rolesSkipped: number;
  usersInserted: number;
  usersUpdated: number;
  usersSkipped: number;
  userRolesInserted: number;
  userRolesSkipped: number;
  pageContentsInserted: number;
  pageContentsSkipped: number;
};

type PageContentSeedRow = {
  id?: number;
  pageKey?: string;
  sectionKey?: string;
  title?: string;
  content?: string;
  type?: string;
  order?: number;
  imageUrl?: string | null;
  metadata?: Record<string, unknown>;
  isActive?: boolean;
};

function loadOptionalPageContent(): PageContentSeedRow[] {
  const candidates = [
    path.join(process.cwd(), 'src/export-pageContent-2026-04-28.json'),
    path.join(
      process.cwd(),
      'apps/tuyen-sinh-api/src/export-pageContent-2026-04-28.json',
    ),
    path.join(__dirname, '..', 'export-pageContent-2026-04-28.json'),
  ];
  for (const filePath of candidates) {
    if (!fs.existsSync(filePath)) continue;
    try {
      const parsed = JSON.parse(fs.readFileSync(filePath, 'utf-8')) as {
        pageContent?: unknown;
      };
      return Array.isArray(parsed.pageContent)
        ? (parsed.pageContent as PageContentSeedRow[])
        : [];
    } catch {
      return [];
    }
  }
  return [];
}

/**
 * Idempotent: giống `pnpm run seed:superadmin` (roles, users, user_roles, page_contents tùy file JSON).
 */
export async function runSuperadminBootstrap(
  em: EntityManager,
  log?: (message: string) => void,
): Promise<SuperadminBootstrapResult> {
  const out: SuperadminBootstrapResult = {
    rolesInserted: 0,
    rolesUpdated: 0,
    rolesSkipped: 0,
    usersInserted: 0,
    usersUpdated: 0,
    usersSkipped: 0,
    userRolesInserted: 0,
    userRolesSkipped: 0,
    pageContentsInserted: 0,
    pageContentsSkipped: 0,
  };

  const L = log ?? (() => undefined);

  L('Seeding roles...');
  for (const roleData of SUPERADMIN_ROLES_DATA) {
    const existing = await em.findOne(Role, { name: roleData.name });
    if (!existing) {
      const role = new Role();
      role.name = roleData.name;
      role.displayName = roleData.displayName;
      role.description = roleData.description;
      role.permissions = roleData.permissions;
      role.isActive = roleData.isActive;
      em.persist(role);
      out.rolesInserted++;
      L(`Created role: ${roleData.name}`);
    } else {
      existing.displayName = roleData.displayName;
      existing.description = roleData.description;
      existing.permissions = roleData.permissions;
      existing.isActive = roleData.isActive;
      em.persist(existing);
      out.rolesUpdated++;
      L(`Updated role: ${roleData.name}`);
    }
  }

  await em.flush();
  L('Roles committed.');

  L('Seeding users...');
  for (const userData of SUPERADMIN_USERS_DATA) {
    const email = userData.email.trim().toLowerCase();
    const existing = await em.findOne(User, { email });
    if (!existing) {
      const user = new User();
      user.email = email;
      user.name = userData.name;
      user.password = userData.password;
      user.bio = userData.bio;
      user.avatar = userData.avatar;
      user.emailVerified = userData.emailVerified;
      user.phone = userData.phone;
      user.address = userData.address;
      user.isActive = userData.isActive;
      em.persist(user);
      out.usersInserted++;
      L(`Created user: ${email}`);
    } else {
      existing.name = userData.name;
      existing.password = userData.password;
      existing.bio = userData.bio;
      existing.avatar = userData.avatar;
      existing.emailVerified = userData.emailVerified;
      existing.phone = userData.phone;
      existing.address = userData.address;
      existing.isActive = userData.isActive;
      em.persist(existing);
      out.usersUpdated++;
      L(`Updated user: ${email}`);
    }
  }

  await em.flush();
  L('Users committed.');

  L('Seeding user roles...');
  for (const link of SUPERADMIN_USER_ROLES_DATA) {
    const before = await em.findOne(UserRole, {
      user: { email: link.userEmail.trim().toLowerCase() },
      role: { name: link.roleName.trim() },
    });
    if (before) {
      out.userRolesSkipped++;
      L(`User role already exists: ${link.userEmail} -> ${link.roleName}`);
      continue;
    }
    const created = await resolveUserRoleLink(em, link);
    if (created) {
      out.userRolesInserted++;
      L(`Created user role: ${link.userEmail} -> ${link.roleName}`);
    }
  }

  await em.flush();
  L('User roles committed.');

  const pageContentData = loadOptionalPageContent();
  L('Seeding page contents...');
  for (const pc of pageContentData) {
    if (!pc.pageKey || !pc.sectionKey) continue;
    const existing = await em.findOne(PageContent, {
      pageKey: pc.pageKey,
      sectionKey: pc.sectionKey,
    });
    if (!existing) {
      const pageContent = new PageContent();
      pageContent.pageKey = pc.pageKey;
      pageContent.sectionKey = pc.sectionKey;
      pageContent.content =
        pc.metadata ??
        (typeof pc.content === 'string' && pc.content.trim()
          ? { value: pc.content }
          : {});
      pageContent.isVisible = pc.isActive ?? true;
      em.persist(pageContent);
      out.pageContentsInserted++;
    } else {
      out.pageContentsSkipped++;
    }
  }

  await em.flush();
  L('Page contents committed.');

  return out;
}

src/seo-metas/seo-metas.controller.ts.content:
/** AUTO-GENERATED — chạy pnpm api:generate:checkin. Không sửa tay; override trong api.app.config.json → native.* */
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
} from '@nestjs/common';
import { ApiOperation, ApiHeader, ApiBody, ApiResponse } from '@nestjs/swagger';
import type { Response } from 'express';
import { SeoMetasService } from './seo-metas.service';
import {
  createSuccessResponse,
  createErrorResponse,
} from '../common/api-response';
import { Permissions } from '../common/permissions.decorator';
import { PERMISSIONS } from '../config/permissions';
import { APP_HEADERS, ADMIN_ROUTES } from '../config/constants';
import { isBulkAction } from '../common/bulk-actions';
import { buildAdminListCrudParams } from '../common/admin-list-params';

@Permissions(PERMISSIONS.SEO_METAS_VIEW)
@Controller(ADMIN_ROUTES.SEO_METAS)
export class SeoMetasController {
  constructor(private readonly service: SeoMetasService) {}

  private getUserId(
    headers: Record<string, string | undefined>,
  ): string | null {
    const id = headers[APP_HEADERS.USER_ID]?.trim();
    return id || null;
  }

  private unauthorized(res: Response): Response {
    const { statusCode, body } = createErrorResponse('Thiếu header X-User-Id', {
      status: 401,
    });
    return res.status(statusCode).json(body);
  }

  @Get()
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('search') search?: string,
    @Query('status') status?: string,
    @Query() query?: Record<string, string>,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const result = await this.service.list(
      buildAdminListCrudParams({ page, limit, search, status, query }),
    );
    const { statusCode, body } = createSuccessResponse({
      data: result.data,
      pagination: result.pagination,
    });
    return res.status(statusCode).json(body);
  }

  @Get('lookup')
  async lookupByPage(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('page') page?: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const normalized = page?.trim();
    if (!normalized) {
      const { statusCode, body } = createErrorResponse('Thiếu query page', {
        status: 400,
      });
      return res.status(statusCode).json(body);
    }
    const row = await this.service.getByPage(normalized);
    const { statusCode, body } = createSuccessResponse(row);
    return res.status(statusCode).json(body);
  }

  @Put('upsert')
  @Permissions(
    PERMISSIONS.SEO_METAS_UPDATE,
    PERMISSIONS.SEO_METAS_MANAGE,
    PERMISSIONS.SETTINGS_UPDATE,
    PERMISSIONS.SETTINGS_MANAGE,
  )
  async upsertByPage(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      page: string;
      title?: string | null;
      description?: string | null;
      keywords?: string | null;
      ogTitle?: string | null;
      ogDescription?: string | null;
      ogImage?: string | null;
      status?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    if (!body?.page?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'page là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    try {
      const saved = await this.service.upsertByPage(body.page.trim(), {
        title: body.title,
        description: body.description,
        keywords: body.keywords,
        ogTitle: body.ogTitle,
        ogDescription: body.ogDescription,
        ogImage: body.ogImage,
        status: body.status,
      });
      const { statusCode, body: okBody } = createSuccessResponse(saved);
      return res.status(statusCode).json(okBody);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : 'Không lưu được SEO meta';
      const { statusCode, body: errBody } = createErrorResponse(message, {
        status: 400,
      });
      return res.status(statusCode).json(errBody);
    }
  }

  @Get(':id')
  async getById(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const row = await this.service.getById(id);
    if (!row) {
      const { statusCode, body } = createErrorResponse('Không tìm thấy', {
        status: 404,
      });
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(row);
    return res.status(statusCode).json(body);
  }

  @Post()
  @Permissions(PERMISSIONS.SEO_METAS_CREATE)
  async create(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      page: string;
      title?: string;
      description?: string;
      keywords?: string;
      ogTitle?: string;
      ogDescription?: string;
      ogImage?: string;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    if (!body?.page?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'page là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const created = await this.service.create({
      page: body.page.trim(),
      title: body.title?.trim(),
      description: body.description?.trim(),
      keywords: body.keywords?.trim(),
      ogTitle: body.ogTitle?.trim(),
      ogDescription: body.ogDescription?.trim(),
      ogImage: body.ogImage?.trim(),
    });
    const { statusCode, body: okBody } = createSuccessResponse(created, {
      status: 201,
    });
    return res.status(statusCode).json(okBody);
  }

  @Put(':id')
  @Permissions(PERMISSIONS.SEO_METAS_UPDATE)
  async update(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body()
    body: {
      page?: string;
      title?: string | null;
      description?: string | null;
      keywords?: string | null;
      ogTitle?: string | null;
      ogDescription?: string | null;
      ogImage?: string | null;
      status?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const updated = await this.service.update(id, {
      page: body?.page?.trim(),
      title: body?.title,
      description: body?.description,
      keywords: body?.keywords,
      ogTitle: body?.ogTitle,
      ogDescription: body?.ogDescription,
      ogImage: body?.ogImage,
      status: body?.status,
    });
    if (!updated) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Không tìm thấy',
        { status: 404 },
      );
      return res.status(statusCode).json(errBody);
    }
    const { statusCode, body: okBody } = createSuccessResponse(updated);
    return res.status(statusCode).json(okBody);
  }

  @Delete(':id')
  @Permissions(PERMISSIONS.SEO_METAS_DELETE)
  async softDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.service.softDelete(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy hoặc đã xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa',
    });
    return res.status(statusCode).json(body);
  }

  @Post(':id/restore')
  @Permissions(PERMISSIONS.SEO_METAS_RESTORE)
  async restore(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.service.restore(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy hoặc chưa xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã khôi phục',
    });
    return res.status(statusCode).json(body);
  }

  @Delete(':id/hard-delete')
  @Permissions(PERMISSIONS.SEO_METAS_MANAGE)
  async hardDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.service.hardDelete(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse('Không tìm thấy', {
        status: 404,
      });
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa vĩnh viễn',
    });
    return res.status(statusCode).json(body);
  }

  @Post('bulk')
  @Permissions(PERMISSIONS.SEO_METAS_MANAGE)
  @ApiOperation({ summary: 'Bulk action on SEO metas' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiBody({ description: 'Bulk action with ids' })
  @ApiResponse({ status: 200, description: 'Bulk action completed' })
  @ApiResponse({ status: 400, description: 'Invalid action' })
  async bulk(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { action?: string; ids?: string[] },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) {
      return this.unauthorized(res);
    }
    const action = body?.action;
    const ids = Array.isArray(body?.ids) ? body.ids : [];
    if (!action || !isBulkAction(action)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Action khong hop le',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const result = await this.service.bulk(action, ids);
    const { statusCode, body: okBody } = createSuccessResponse(
      { affected: result.success, message: result.message },
      { message: result.message },
    );
    return res.status(statusCode).json(okBody);
  }
}

